'use strict';
const menuButton=document.querySelector('.menu-button');
const navigation=document.querySelector('#navigation');
function closeMenu(){menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Open navigation');navigation.classList.remove('open');}
menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'Close navigation':'Open navigation');navigation.classList.toggle('open',open)});
navigation.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
document.addEventListener('click',e=>{if(!e.target.closest('.header'))closeMenu()});
window.matchMedia('(min-width:821px)').addEventListener('change',e=>{if(e.matches)closeMenu()});
const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const serviceDetails={
'Website Design & Development':{number:'01',mark:'⌘',summary:'A clear, considered website that gives your business a sharper first impression and makes it easy for the right people to take the next step.',deliverables:['Discovery and content direction','Responsive page and interface design','Accessible, mobile-first development','CMS, forms, or commerce setup','Launch checks and handover'],process:['Understand your audience and goals','Shape the structure and visual direction','Design, build, and refine together','Launch with a clear handover']},
'Brand Design & Guideline':{number:'02',mark:'✳',summary:'A distinctive identity system that gives your business a recognisable voice across every place people meet your brand.',deliverables:['Brand positioning foundations','Logo and responsive mark system','Colour, typography, and image direction','Social and presentation templates','Practical brand guidelines'],process:['Define the character of your brand','Explore and test a focused direction','Build the identity system','Package the rules for everyday use']},
'Digital Marketing':{number:'03',mark:'◎',summary:'A practical marketing plan and content direction built around your audience, your voice, and the business outcome you want to improve.',deliverables:['Audience and channel review','Content pillars and campaign ideas','Social content direction','Monthly or launch campaign planning','Performance review and next actions'],process:['Find the clearest opportunity','Plan the message and channel mix','Create, publish, and learn','Improve the next cycle with evidence']},
'Paid Advertising':{number:'04',mark:'↗',summary:'Focused paid campaigns with thoughtful creative, clear targeting, and simple reporting that connects spend to meaningful action.',deliverables:['Campaign and audience strategy','Ad creative and copy direction','Landing page recommendations','Tracking and conversion setup','Performance reporting and optimisation'],process:['Set the goal and success measure','Build audiences and creative tests','Launch with careful tracking','Review results and refine']},
'Search Engine Optimization (SEO)':{number:'05',mark:'⊕',summary:'A stronger search foundation that helps the right people find your business through useful content and a well-structured website.',deliverables:['Technical SEO review','Search intent and keyword direction','On-page structure and metadata','Content opportunities and briefs','Progress tracking and recommendations'],process:['Audit the current search foundation','Prioritise the highest-value fixes','Improve pages and content','Measure visibility and iterate']},
};
if(window.cloudNestData){for(const [i,s]of window.cloudNestData.services.entries()){serviceDetails[s.name]={number:String(i+1).padStart(2,'0'),mark:s.icon,summary:s.description,deliverables:s.deliverables.split('\n').filter(Boolean),process:s.process.split('\n').filter(Boolean)}}}
const serviceDialog=document.querySelector('#service-dialog');let serviceTrigger=null;
function openServiceDetails(name){const d=serviceDetails[name]||serviceDetails['Website Design & Development'];serviceTrigger=document.querySelector(`[data-service="${CSS.escape(name)}"]`);document.querySelector('#service-dialog-number').textContent=d.number;document.querySelector('#service-dialog-mark').textContent=d.mark;document.querySelector('#service-dialog-title').textContent=name;document.querySelector('#service-dialog-summary').textContent=d.summary;const deliverables=document.querySelector('#service-dialog-deliverables'),process=document.querySelector('#service-dialog-process');deliverables.replaceChildren();process.replaceChildren();d.deliverables.forEach(item=>{const li=document.createElement('li');li.textContent=item;deliverables.append(li)});d.process.forEach(item=>{const li=document.createElement('li');li.textContent=item;process.append(li)});serviceDialog.showModal();serviceDialog.scrollTop=0;document.body.style.overflow='hidden'}
document.querySelectorAll('[data-service]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();openServiceDetails(a.dataset.service)}));
serviceDialog.querySelector('.dialog-close').addEventListener('click',()=>window.cloudNestMotion.closeDialog(serviceDialog));serviceDialog.querySelector('.service-contact-button').addEventListener('click',async()=>{const name=serviceTrigger?.dataset.service||'Not sure yet';await window.cloudNestMotion.closeDialog(serviceDialog);document.querySelector('#service-select').value=name;document.querySelector('#contact').scrollIntoView({behavior:reduceMotion?'auto':'smooth'});setTimeout(()=>document.querySelector('#service-select').focus(),reduceMotion?0:500)});serviceDialog.addEventListener('click',e=>{if(e.target===serviceDialog){const rect=serviceDialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)window.cloudNestMotion.closeDialog(serviceDialog)}});serviceDialog.addEventListener('close',()=>{document.body.style.overflow='';serviceTrigger?.focus()});
document.querySelectorAll('[data-plan]').forEach(a=>a.addEventListener('click',()=>{document.querySelector('#plan-select').value=a.dataset.plan}));
const articles={
website:{title:'Before you redesign your website, ask these five questions',body:[['Start with the problem, not the mood board.','A redesign is a chance to make your website more useful. Before choosing colours or collecting references, write down what needs to change. Is the offer unclear? Is it difficult to enquire? Does the website no longer reflect your business? A clear problem gives the project a purpose.'],['1. Who is the website for?','Describe the people you want to reach, what they need, and what they may already know. A first-time customer needs a different introduction from an existing client. Use that distinction to decide what belongs on the page.'],['2. What should visitors do next?','Choose the most useful next step for each page: understand a service, compare options, or start a conversation. Keep that action easy to find and explain what happens after someone takes it.'],['3. What content can you bring?','Gather your service descriptions, photography, brand files, and answers to common questions. Identify anything that needs to be written or created. Content is part of the project, not something to squeeze in at the end.'],['4. What should you keep?','Review the existing website before replacing it. Keep useful information, clear language, and familiar routes that still serve your audience. A redesign can build on what works.'],['5. How will you judge the result?','Set a practical goal you can review after launch. That might be fewer confused enquiries, a simpler booking process, or a clearer explanation of your services. Agree on the goal before judging the design.']]},
brand:{title:'A good brand is more than a beautiful logo',body:[['Think in systems.','A logo is an important part of a brand, but it rarely appears alone. It sits next to words, photographs, colour, typography, and layout. Those choices need to feel like they belong to the same business.'],['Start with what you want to communicate.','Write down what your business does, who it serves, and how you want people to describe it. Be specific. “Clear and approachable” gives a designer a more useful direction than “make it premium” on its own.'],['Give every element a job.','Choose type that suits the way your business communicates. Use colour with a clear hierarchy. Decide how images should feel, and how headings should sound. A useful identity makes those decisions easier to repeat.'],['Create guidelines people can actually use.','A brand guide should answer practical questions: which logo belongs on a dark background, how much space it needs, which colours and type styles to use, and what to avoid. Real examples make the rules easier to follow.'],['Leave room for the brand to grow.','Test the system across a website, a social post, and a simple document. It should feel connected without making every piece identical. The aim is a recognisable identity that can adapt to the work ahead.']]},
project:{title:'How to turn a big idea into a useful project brief',body:[['You do not need all the answers.','A good brief starts a useful conversation. It explains what you are trying to achieve and gives your creative or development partner enough context to ask better questions.'],['Describe the problem in one paragraph.','Explain what happens today, who it affects, and what you want to improve. Keep the focus on the need before choosing a particular feature or technology.'],['Separate essentials from possibilities.','List what the first version must do, then keep future ideas in a separate list. This makes it easier to discuss a practical starting scope without losing the bigger picture.'],['Share references with a reason.','When you share a website or visual reference, explain what you like about it. It might be the navigation, tone, clarity, or use of space. A reference becomes more useful when your partner understands the reason behind it.'],['Be open about constraints.','Include your intended launch date, budget range if known, available content, and who will review the work. Mention existing systems that need to be connected. These details help shape a realistic plan.'],['End with a definition of success.','Describe what a useful finished result would let you or your customers do. That shared definition gives both sides something concrete to work towards.']]}
};
if(window.cloudNestData){for(const a of window.cloudNestData.blog){articles[a.id]={title:a.title,body:a.body.split('\n\n').map(p=>{const lines=p.split('\n');return lines.length>1?[lines.shift(),lines.join('\n')]:['',p]})}}}
const dialog=document.querySelector('#article-dialog');let articleTrigger=null;
document.querySelectorAll('[data-article]').forEach(button=>button.addEventListener('click',()=>{const article=articles[button.dataset.article];articleTrigger=button;document.querySelector('#article-title').textContent=article.title;const body=document.querySelector('#article-body');body.replaceChildren();article.body.forEach(([heading,text])=>{const h=document.createElement('h3'),p=document.createElement('p');h.textContent=heading;p.textContent=text;body.append(h,p)});dialog.showModal();dialog.scrollTop=0;document.body.style.overflow='hidden'}));
function closeArticle(){window.cloudNestMotion.closeDialog(dialog)}
dialog.querySelector('.dialog-close').addEventListener('click',closeArticle);dialog.querySelector('.article-done').addEventListener('click',closeArticle);
dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeArticle()}});
dialog.addEventListener('close',()=>{document.body.style.overflow='';articleTrigger?.focus()});
document.querySelector('#project-form').addEventListener('submit',e=>{e.preventDefault();if(window.cloudNestEnquiryConnected)return;const form=e.currentTarget;if(!form.reportValidity())return;const data=new FormData(form);const brief=['CLOUD NEST — PROJECT BRIEF','',`Name: ${data.get('name')}`,`Email: ${data.get('email')}`,`Company: ${data.get('company')||'Not specified'}`,`Service: ${data.get('service')}`,`Project direction: ${data.get('plan')}`,'','PROJECT DETAILS',data.get('message'),'','This brief was prepared locally. It has not been sent to Cloud Nest.'].join('\n');const blob=new Blob([brief],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='cloud-nest-project-brief.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#form-status').textContent='Your brief is ready. Check your downloads and keep it to share. Nothing has been sent.'});
if(document.querySelector('#year'))document.querySelector('#year').textContent=new Date().getFullYear();
